import java.util.*;
import java.math.BigInteger;

public class Main {

    static String toStringStr(String s) {
        return "\"" + s + "\"";
    }

    static String toStringCharArray(char[] s) {
        return toStringStr(new String(s));
    }

    static String toStringBool(boolean b) {
        return b ? "true" : "false";
    }

    static String toStringVectorBoolean(List<Boolean> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (Boolean b : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(toStringBool(b));
        }
        res.append("}");
        return res.toString();
    }

    static String toStringBitSet(BitSet v, int N) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < N; i++) {
            res.append(v.get(i) ? '1' : '0');
        }
        return res.toString();
    }

    static <T> String toStringList(Iterable<T> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (T x : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(toStringGeneric(x));
        }
        res.append("}");
        return res.toString();
    }

    static <A, B> String toStringPair(Map.Entry<A, B> p) {
        return "(" + toStringGeneric(p.getKey()) + ", " + toStringGeneric(p.getValue()) + ")";
    }

    static <A, B, C> String toStringTriple(Tuple3<A, B, C> p) {
        return "(" + toStringGeneric(p.first) + ", " + toStringGeneric(p.second) + ", " + toStringGeneric(p.third) + ")";
    }

    static <A, B, C, D> String toStringQuadruple(Tuple4<A, B, C, D> p) {
        return "(" + toStringGeneric(p.first) + ", " + toStringGeneric(p.second) + ", " + toStringGeneric(p.third) + ", " + toStringGeneric(p.fourth) + ")";
    }

    static String toStringGeneric(Object obj) {
        if (obj == null) {
            return "null";
        } else if (obj instanceof String) {
            return toStringStr((String) obj);
        } else if (obj instanceof CharSequence) {
            return toStringStr(obj.toString());
        } else if (obj instanceof Boolean) {
            return toStringBool((Boolean) obj);
        } else if (obj instanceof List<?>) {
            return toStringList((Iterable<?>) obj);
        } else if (obj instanceof Map.Entry<?, ?>) {
            return toStringPair((Map.Entry<?, ?>) obj);
        } else if (obj instanceof Tuple3<?, ?, ?>) {
            return toStringTriple((Tuple3<?, ?, ?>) obj);
        } else if (obj instanceof Tuple4<?, ?, ?, ?>) {
            return toStringQuadruple((Tuple4<?, ?, ?, ?>) obj);
        } else if (obj instanceof BitSet) {
            // No direct size info, so assuming maximum size is passed separately
            return toStringBitSet((BitSet) obj, ((BitSet) obj).size());
        } else {
            return obj.toString();
        }
    }

    static class Tuple3<A, B, C> {
        public A first;
        public B second;
        public C third;
        public Tuple3(A a, B b, C c) {
            this.first = a;
            this.second = b;
            this.third = c;
        }
    }

    static class Tuple4<A, B, C, D> {
        public A first;
        public B second;
        public C third;
        public D fourth;
        public Tuple4(A a, B b, C c, D d) {
            this.first = a;
            this.second = b;
            this.third = c;
            this.fourth = d;
        }
    }

    // Modular inverse using Extended Euclidean Algorithm
    static long modularInverse(long a, long m) {
        long m0 = m;
        long y = 0, x = 1;
        if (m == 1)
            return 0;
        while (a > 1) {
            // q is quotient
            long q = a / m;
            long t = m;
            // m is remainder now, process same as Euclid's algo
            m = a % m;
            a = t;
            t = y;
            // Update x and y
            y = x - q * y;
            x = t;
        }
        // Make x positive
        if (x < 0)
            x += m0;
        return x;
    }

    static class ModularType {
        long val;
        static long MOD;

        ModularType() {
            this.val = 0;
        }

        ModularType(long x) {
            this.val = normalize(x);
        }

        static long normalize(long x) {
            long v = x % MOD;
            if (v < 0) v += MOD;
            return v;
        }

        ModularType add(ModularType other) {
            this.val += other.val;
            if (this.val >= MOD) this.val -= MOD;
            return this;
        }

        ModularType subtract(ModularType other) {
            this.val -= other.val;
            if (this.val < 0) this.val += MOD;
            return this;
        }

        ModularType multiply(ModularType other) {
            this.val = (this.val * other.val) % MOD;
            return this;
        }

        ModularType divide(ModularType other) {
            return this.multiply(new ModularType(modularInverse(other.val, MOD)));
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod_value = sc.nextLong();
        ModularType.MOD = mod_value;

        List<ModularType> fact = new ArrayList<>();
        List<ModularType> inv_fact = new ArrayList<>();
        fact.add(new ModularType(1));
        inv_fact.add(new ModularType(1));
        // C function
        // For clarity, define helper within main
        java.util.function.BiFunction<Integer, Integer, ModularType> C = (x, y) -> {
            int sz = Math.max(x, y);
            while (fact.size() <= sz) {
                int s = fact.size();
                fact.add(fact.get(fact.size() - 1).multiply(new ModularType(s)));
                inv_fact.add(new ModularType(1).divide(fact.get(fact.size() - 1)));
            }
            if (y < 0 || y > x) return new ModularType(0);
            return fact.get(x).multiply(inv_fact.get(y)).multiply(inv_fact.get(x - y));
        };
        // Precompute ways_arr and ways_count
        ModularType[] ways_count = new ModularType[m + 1];
        ModularType[] ways_arr = new ModularType[m + 1];
        for (int i = 0; i <= m; i++) {
            ways_count[i] = new ModularType(0);
            ways_arr[i] = new ModularType(0);
        }
        ways_count[0] = new ModularType(1);
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int l = j, r = i - 1 - j;
                ModularType term = ways_count[l]
                        .multiply(ways_count[r])
                        .multiply(C.apply(l + r, l))
                        .multiply(new ModularType(l + r + 2));
                ways_arr[i].add(term);
            }
            for (int j = 0; j < i; j++) {
                int l = j, r = i - 1 - j;
                ModularType add = (new ModularType(l).multiply(new ModularType(l + 1)).add(new ModularType(r).multiply(new ModularType(r + 1)))).divide(new ModularType(2));
                ModularType term = ways_count[l]
                        .multiply(ways_count[r])
                        .multiply(C.apply(l + r, l))
                        .multiply(add);
                ways_count[i].add(term);
            }
        }

        ModularType[][] dp = new ModularType[n + 1][m + 1];
        ModularType[][] ways_dp = new ModularType[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new ModularType(0);
                ways_dp[i][j] = new ModularType(0);
            }
        }
        ways_dp[0][0] = new ModularType(1);
        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= Math.min(m, i); s++) {
                if (s == i) {
                    dp[i][s] = ways_count[s];
                    continue;
                }
                for (int d = 1; d <= s + 1; d++) {
                    if (i - d >= 0 && s + 1 - d >= 0) {
                        ModularType ft = dp[i - d][s + 1 - d];
                        ModularType way = ways_dp[i - d][s + 1 - d];
                        int add = d - 1;
                        ways_dp[i][s].add(way.multiply(ways_count[add]).multiply(C.apply(s, add)));
                        ModularType term = (way.multiply(ways_count[add]).add(ways_dp[i - d][s + 1 - d].multiply(ft))).multiply(C.apply(s, add));
                        dp[i][s].add(term);
                    }
                }
            }
        }
        System.out.println(dp[n][m].val);
        sc.close();
    }
}
